import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  useSyncExternalStore,
} from "react";
import {
  getAccessTokenSnapshot,
  subscribeAccessToken,
} from "../service/authAccessStore";
import { applyAuthTokens, clearAuthTokens } from "../service/authTokens";
import {
  formatAuthError,
  loginRequest,
  refreshTokensRequest,
  registerRequest,
} from "../service/authService";
import { readRefreshToken } from "../service/refreshTokenCookie";

const AuthContext = createContext(null);

function useAccessTokenExternal() {
  return useSyncExternalStore(
    subscribeAccessToken,
    getAccessTokenSnapshot,
    () => null
  );
}

export function AuthProvider({ children }) {
  const accessToken = useAccessTokenExternal();
  const [authReady, setAuthReady] = useState(false);

  useEffect(() => {
    let cancelled = false;

    (async () => {
      const rt = readRefreshToken();
      if (!rt) {
        if (!cancelled) setAuthReady(true);
        return;
      }

      try {
        const { ok, data } = await refreshTokensRequest(rt);
        if (!cancelled && ok && data?.accessToken && data?.refreshToken) {
          applyAuthTokens(data, readRememberFlagSafe());
        } else if (!cancelled && !ok) {
          clearAuthTokens();
        }
      } catch {
        if (!cancelled) clearAuthTokens();
      } finally {
        if (!cancelled) setAuthReady(true);
      }
    })();

    return () => {
      cancelled = true;
    };
  }, []);

  const auth = useMemo(() => ({ accessToken }), [accessToken]);

  const applyTokens = useCallback((tokenBody, remember) => {
    applyAuthTokens(tokenBody, remember);
  }, []);

  const login = useCallback(async (email, password, remember) => {
    const r = await loginRequest(email, password);
    if (r.ok && r.data?.accessToken && r.data?.refreshToken) {
      applyTokens(r.data, remember);
      return { ok: true };
    }
    return { ok: false, message: formatAuthError(r.data) };
  }, [applyTokens]);

  const register = useCallback(async (email, password, nome, remember) => {
    const r = await registerRequest(email, password, nome);
    if (r.ok && r.data?.accessToken && r.data?.refreshToken) {
      applyTokens(r.data, remember);
      return { ok: true };
    }
    return { ok: false, message: formatAuthError(r.data) };
  }, [applyTokens]);

  const logout = useCallback(() => {
    clearAuthTokens();
  }, []);

  const value = useMemo(
    () => ({
      auth,
      authReady,
      isAuthenticated: !!accessToken,
      login,
      register,
      logout,
    }),
    [auth, authReady, accessToken, login, register, logout]
  );

  return (
    <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
  );
}

function readRememberFlagSafe() {
  try {
    const { readRememberFlag } = require("../service/refreshTokenCookie.js");
    return readRememberFlag();
  } catch {
    return false;
  }
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) {
    throw new Error("useAuth deve ser usado dentro de AuthProvider");
  }
  return ctx;
}
